function renderHotbar(){const key=['1','2','3','4','5','6','R'];$('hotbar').innerHTML=p.loadout.map((id,i)=>{let s=DB.skills.find(s=>s.id===id);return `<button class="skillKey ${i===6?'ultimate':''}" data-id="${id}" title="${s.name} · ${s.cost} 자원 · ${s.cooldown}초" style="--skill-color:${tagColor(s.tag)}"><span class="key">${key[i]}</span>${iconHtml(skillIconCell(DB,s),'skillIcon')}<span class="name">${s.name}</span><span class="cool" hidden></span></button>`;}).join('');for(const b of $('hotbar').children)b.onclick=()=>cast(DB.skills.find(s=>s.id===b.dataset.id));}
