let last=performance.now();function frame(now){requestAnimationFrame(frame);let dt=Math.min((now-last)/1000,.05);last=now;if(hitstop>0){hitstop-=dt;dt*=.12;}update(dt);let center=started?hero.position:new THREE.Vector3(-2,0,0);const desired=new THREE.Vector3(center.x+18,24,center.z+21);camera.position.lerp(desired,1-Math.exp(-dt*5));const look=center.clone();look.y=.3;if(settings.shake&&shake>0){look.x+=rnd(-shake,shake);look.z+=rnd(-shake,shake);shake=Math.max(0,shake-dt);}camera.lookAt(look);sun.position.set(center.x-12,24,center.z+10);sun.target.position.copy(center);updateEnemyLabels();updateWorldLabels();updateTargetMarkers();renderer.render(scene,camera);}requestAnimationFrame(frame);
